import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.20 (2026-10-25) = THE PET WIDGET'S DATA (docs/answered/pets.md 2026-10-25 PET WIDGET: Skyy "we need a pet widget" + popup "Pet + summon
  portraits, Level XP bar, Summon health + ability"; the widget itself is SkyyHud 0.3.37). Lean addition, read-only.
  1. NEW BRIDGE pets:fn:hud (java.util.function.Function, class PetHudFn; published in setup, taken off at stop - only while it still holds
     ours): apply(UUID | its String | Object[] { UUID }) -> String[2] { pet slot line, summon slot line } ("" = that slot is empty, or the
     summon slot is locked); null = cannot answer (pets off, profile switching, the record not loaded, a bad file). MEMORY ONLY: the
     online player's cached record (PetStore.KEYOF / REC - never a disk load), the live summoned creature (PetViews.view) and the
     DOWN / Radiance clocks; any thread; never throws. One line = 17 fields split by '|' (a '|' in a text becomes '/'):
       0 slot (1 / 2) | 1 pet id | 2 kind | 3 rarity 1-6 | 4 kind name ("Wolf") | 5 level | 6 level cap | 7 XP into the level |
       8 XP the next level needs (0 = at the cap) | 9 icon item (the 0.4.18 rarity portrait Skyy_PetIcon_<Kind>_<Rarity>; the plain
       portrait when none; "" = none) | 10 health now ("" = this summon has no health pool, "-" = not in the world right now) |
       11 health max | 12 ability name ("" = none: the secret dragons' perk, else "Bite" for a dragon that fights) |
       13 ability state: "ok" ready, "f" fighting (has a target), "r" ridden, "p" passive (a secret perk with no cooldown: Void
          Strike / Blood Drinker / Crystal Skin), "c<ms>" cooling down (Radiance's heal clock), "d<ms>" DOWN (back in its slot after
          <ms>) | 14 the cooldown bar 0.000 - 1.000 (1 = ready); "" = no real cooldown (Bite, the passive perks - FIX petwidfix: no
          bar, so a permanent full bar never reads as a cooldown) | 15 state ("" / "down" /
          "riding") | 16 the ability's colour (#rrggbb; the secret dragons' own colour)
     Health / ability are for the SUMMON slot only (the pet slot line leaves 10-16 empty). Only dragons have a health pool (0.4.12; with
     Dragon fighting on); a DOWN dragon = health 0 + "d<ms>".
  SAVED DATA: none. No new system, command, row or item. FLOOR (rollback): rolls back alone to 0.4.19 (pets:fn:hud goes away = SkyyHud
  0.3.37's pet widget hides itself). The 0.4.19 / 0.4.17 / 0.4.15 / 0.4.11 floors stand.
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.19.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.20.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.19"') and P.has('sfn = cls("PetSecretFn")') and not P.has("PetHudFn"), "not the generated SkyyPets 0.4.19 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.19 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_19_patch.py from SkyyPets 0.4.18
(build_skyypets_0.4.18.py, the SET pin, itself generated by tools/pets_0_4_18_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.19.py   -> SkyyPets/SkyyPets-0.4.19.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.19.py
''', '''"""SkyyPets 0.4.20 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_20_patch.py from SkyyPets 0.4.19
(build_skyypets_0.4.19.py, the SET pin, itself generated by tools/pets_0_4_19_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.20.py   -> SkyyPets/SkyyPets-0.4.20.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.20.py

''' + NOTE + '''
SkyyPets 0.4.19 (generated by tools/pets_0_4_19_patch.py from 0.4.18) - everything below is still true unless 0.4.20 above says otherwise:
''')
P.rep('VERSION = "0.4.19"\n', 'VERSION = "0.4.20"\n')

# ======================================================================================================== PetHudFn (after PetSecretFn)
HUDFN = r'''# 0.4.20 PetHudFn: the bridge pets:fn:hud (SkyyHud 0.3.37's pet widget). apply(UUID | String | Object[] { UUID }) -> String[2] { pet slot line,
# summon slot line } ("" = empty / locked); null = cannot answer. Memory only (the cached record of an online player, the live summon, the
# DOWN / Radiance clocks) - never a disk load, any thread, never throws. The 17 '|' fields: tools/pets_0_4_20_patch.py NOTE.
hfn = cls("PetHudFn")
hfn.addInterface(pool.get("java.util.function.Function"))
F(hfn, "public static final java.util.concurrent.atomic.AtomicLong CALLS = new java.util.concurrent.atomic.AtomicLong();")
C(hfn, "public PetHudFn() { }")
M(hfn, r"""
public static String safe(String s) {
  if (s == null) return "";
  return @PKG@.PetsLog.clean(s).replace('|', '/');
}""")
# done of total as "0.000" - "1.000" (total <= 0 = "1.000")
M(hfn, r"""
public static String frac(long done, long total) {
  if (total <= 0L || done >= total) return "1.000";
  if (done <= 0L) return "0.000";
  long v = (done * 1000L + total / 2L) / total;
  if (v > 1000L) v = 1000L;
  String f = String.valueOf(1000L + v).substring(1);
  return v >= 1000L ? "1.000" : "0." + f;
}""")
M(hfn, r"""
public static String line(java.util.UUID u, @PKG@.PetRec r, int slot, long now) {
  String id = r.active(slot);
  if (id == null || id.length() == 0) return "";
  if (slot == 2 && !@PKG@.PetBuff.slot2Open(r)) return "";
  String k = r.kindOf(id);
  int rar = r.rarityOf(id);
  int lv = r.levelOf(id);
  int cap = r.capOf(id);
  long xp = r.xpOf(id);
  long need = lv >= cap ? 0L : @PKG@.PetMath.need(lv + 1);
  String ic = @PKG@.PetEggDefs.portraitR(k, rar);
  if (ic == null) ic = @PKG@.PetEggDefs.portrait(k);
  if (ic == null) ic = "";
  String hp = "", hpm = "", ab = "", ast = "", afr = "", st = "", acol = "";
  if (slot == 2) {
    boolean dg = @PKG@.PetDragon.isDragon(k);
    boolean fights = dg && @PKG@.PetFight.on();
    @PKG@.PetView v = @PKG@.PetViews.view(u, 2);
    if (v != null && (v.gone || !id.equals(v.petId))) v = null;
    long dl = dg ? @PKG@.PetDragon.downLeft(id) : 0L;
    if (fights) {
      if (dl > 0L) { hp = "0"; hpm = "0"; }
      else if (v != null && v.fhpMax > 0.0) {
        double h = v.fhp < 0.0 ? 0.0 : (v.fhp > v.fhpMax ? v.fhpMax : v.fhp);
        hp = String.valueOf((long) Math.ceil(h));
        hpm = String.valueOf(Math.round(v.fhpMax));
      } else { hp = "-"; hpm = "-"; }
    }
    String pk = @PKG@.PetSecret.abilName(k);
    if (pk != null && pk.length() > 0) { ab = pk; acol = @PKG@.PetSecret.colOf(k); }
    else if (fights) { ab = "Bite"; acol = "#d6e4ee"; }
    if (ab.length() > 0) {
      if (dl > 0L) {
        long dm = @PKG@.PetDragon.downMs(lv);
        if (dm < dl) dm = dl;
        ast = "d" + dl; afr = frac(dm - dl, dm); st = "down";
      } else if (v != null && v.riding) { ast = "r"; afr = @PKG@.PetSecret.idx(k) == 2 ? "1.000" : ""; st = "riding"; }
      else if (@PKG@.PetSecret.idx(k) == 2) {
        Object nx = @PKG@.PetSecret.LIGHT_AT.get(id);
        long tot = @PKG@.PetSecret.lightMs();
        long left = nx instanceof Long ? ((Long) nx).longValue() - @PKG@.PetFight.now() : 0L;
        if (left > tot) left = tot;
        if (left > 0L) { ast = "c" + left; afr = frac(tot - left, tot); }
        else { ast = "ok"; afr = "1.000"; }
      } else if (fights && v != null && v.ftgt != null) { ast = "f"; afr = ""; }
      else if (pk != null && pk.length() > 0) { ast = "p"; afr = ""; }     // FIX petwidfix: a passive perk, no cooldown bar
      else { ast = "ok"; afr = ""; }
    }
  }
  StringBuilder b = new StringBuilder();
  b.append(slot).append('|').append(safe(id)).append('|').append(safe(k)).append('|').append(rar).append('|').append(safe(@PKG@.PetOps.kindName(r, id)));
  b.append('|').append(lv).append('|').append(cap).append('|').append(xp).append('|').append(need).append('|').append(safe(ic));
  b.append('|').append(hp).append('|').append(hpm).append('|').append(safe(ab)).append('|').append(ast).append('|').append(afr).append('|').append(st).append('|').append(safe(acol));
  return b.toString();
}""")
M(hfn, r"""
public Object apply(Object o) {
  try {
    CALLS.incrementAndGet();
    Object a = o;
    if (a instanceof Object[]) { Object[] x = (Object[]) a; a = x.length > 0 ? x[0] : null; }
    java.util.UUID u = null;
    if (a instanceof java.util.UUID) u = (java.util.UUID) a;
    else if (a instanceof String) { try { u = java.util.UUID.fromString(((String) a).trim()); } catch (Throwable b) { u = null; } }   // a bad text = null, no log line
    if (u == null || !@PKG@.PetsCfg.ON || @PKG@.PetStore.DIR == null || @PKG@.PetOps.busy(u)) return null;
    Object k = @PKG@.PetStore.KEYOF.get(u);
    if (k == null) k = @PKG@.PetStore.pkey(u);
    Object ro = k == null ? null : @PKG@.PetStore.REC.get(k);
    if (!(ro instanceof @PKG@.PetRec)) return null;
    @PKG@.PetRec r = (@PKG@.PetRec) ro;
    if (r.bad) return null;
    long now = System.currentTimeMillis();
    return new String[] { line(u, r, 1, now), line(u, r, 2, now) };
  } catch (Throwable t) {
    @PKG@.PetsLog.warnOnce("hudfn:" + t.getClass().getName(), "pets:fn:hud failed (logged once): " + t);
    return null;
  }
}""")
'''
P.rep('''# ---- every second for the active record (PetTickSys, the world thread): credits (+ their forced saves) and the ready lines
M(hy, r"""
public static void tickRec(''', HUDFN + '''# ---- every second for the active record (PetTickSys, the world thread): credits (+ their forced saves) and the ready lines
M(hy, r"""
public static void tickRec(''')

# ======================================================================================================== publish + take off + ready line
P.rep('''  @PKG@.PetsLog.bridge().put("pets:fn:secretRoll", new @PKG@.PetSecretFn(1));        // 0.4.19: the same after the word's chance
''', '''  @PKG@.PetsLog.bridge().put("pets:fn:secretRoll", new @PKG@.PetSecretFn(1));        // 0.4.19: the same after the word's chance
  @PKG@.PetsLog.bridge().put("pets:fn:hud", new @PKG@.PetHudFn());                   // 0.4.20: the SkyyHud pet widget's lines
''')
P.rep('''    for (int i = 0; i < sk.length; i++) { Object g = br.get(sk[i]); if (g instanceof @PKG@.PetSecretFn) br.remove(sk[i], g); }
''', '''    for (int i = 0; i < sk.length; i++) { Object g = br.get(sk[i]); if (g instanceof @PKG@.PetSecretFn) br.remove(sk[i], g); }
    Object hf = br.get("pets:fn:hud");          // 0.4.20: only ours
    if (hf instanceof @PKG@.PetHudFn) br.remove("pets:fn:hud", hf);
''')
P.rep('''"; 0.4.19: " + @PKG@.PetSecret.text() + "; kit @KITID@''', '''"; 0.4.19: " + @PKG@.PetSecret.text() + "; 0.4.20: pets:fn:hud (the SkyyHud pet widget); kit @KITID@''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0 + 1, "0.4.20 adds one class (PetHudFn), no system or command"
_i = P.s.index
assert _i('sfn = cls("PetSecretFn")') < _i('hfn = cls("PetHudFn")') < _i("public static void tickRec(") < _i('plug = cls("SkyyPetsPlugin"'), "0.4.20: PetHudFn after every class it calls"
for _dep in ("public static String portraitR(", "public static long downMs(", "public static long downLeft(", "public static boolean slot2Open(",
             "public static @PKG@.PetView view(java.util.UUID u, int slot)", "public static String kindName(", "public static long lightMs()",
             "public static String abilName(", "public static boolean busy(java.util.UUID u)", "public static long need(int level)"):
    assert _i(_dep) < _i('hfn = cls("PetHudFn")'), "0.4.20: methods before callers: " + _dep
P.finish()
